import { useEffect, useState, useCallback, useMemo } from "react"
import { Link } from "@tanstack/react-router"
import { Plus, ArrowUpRight } from "lucide-react"
import { signOut, useSession } from "../lib/auth-client"
import { Button } from "../components/ui/button"
import PageHeader from "../components/ui/page-header"
import PageFooter from "../components/ui/page-footer"
import SectionCards from "../components/SectionCards"
import ActivityTimeline from "../components/ActivityTimeline"
import type { IWalletTransaction, WaveResponse, ITransaction } from "@/types"
import { formatCurrency } from "@/lib/utils"

export default function HomePage() {
  const { data: session } = useSession()
  const user = session!.user
  const [accounts, setAccounts] = useState<IWalletTransaction[]>([])
  const [transactions, setTransactions] = useState<ITransaction[]>([])
  const [loadingAccounts, setLoadingAccounts] = useState(true)
  const [loadingTransactions, setLoadingTransactions] = useState(true)

  const userAccountNumbers = useMemo(() => new Set(accounts.map((a) => String(a.accountNumber))), [accounts])

  const fetchAccounts = useCallback(async () => {
    setLoadingAccounts(true)
    try {
      const res = await fetch(`/api/wallet/users/${user.id}/accounts`)
      if (!res.ok) throw new Error(`HTTP ${res.status}`)
      const json: WaveResponse<IWalletTransaction[]> = await res.json()
      setAccounts(json.ok ? json.data : [])
    } catch {
      setAccounts([])
    } finally {
      setLoadingAccounts(false)
    }
  }, [user.id])

  const fetchTransactions = useCallback(async () => {
    setLoadingTransactions(true)
    try {
      const res = await fetch(`/api/wallet/users/${user.id}/transactions`)
      if (!res.ok) throw new Error(`HTTP ${res.status}`)
      const json: WaveResponse<ITransaction[]> = await res.json()
      if (json.ok) {
        const sorted = json.data.sort(
          (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
        )
        setTransactions(sorted)
      }
    } catch {
      setTransactions([])
    } finally {
      setLoadingTransactions(false)
    }
  }, [user.id])

  useEffect(() => {
    fetchAccounts()
    fetchTransactions()
  }, [fetchAccounts, fetchTransactions])

  const totalBalance = accounts.reduce((sum, a) => sum + a.balance, 0)

  const successCount = transactions.filter((tx) => tx.status === "success").length
  const pendingCount = transactions.filter((tx) => tx.status === "pending").length
  const totalVolume = transactions.reduce((sum, tx) => sum + Number(tx.amount), 0)

  const cardData = loadingAccounts
    ? []
    : [
        {
          title: "Total Balance",
          value: formatCurrency(totalBalance),
          subtitle: `${accounts.length} account${accounts.length !== 1 ? "s" : ""}`,
          trend: { value: `${accounts.length > 0 ? "+" : ""}${accounts.length}`, positive: accounts.length > 0 },
        },
        {
          title: "Transaction Volume",
          value: formatCurrency(totalVolume),
          subtitle: `${transactions.length} transaction${transactions.length !== 1 ? "s" : ""}`,
        },
        {
          title: "Success Rate",
          value: transactions.length > 0 ? `${Math.round((successCount / transactions.length) * 100)}%` : "\u2014",
          subtitle: `${successCount} of ${transactions.length} succeeded`,
          trend: successCount > 0 ? { value: `${successCount}`, positive: true } : undefined,
        },
        {
          title: "Pending",
          value: String(pendingCount),
          subtitle: pendingCount === 1 ? "1 awaiting confirmation" : `${pendingCount} awaiting confirmation`,
        },
      ]

  const handleSignOut = async () => {
    await signOut()
  }

  return (
    <>
      <PageHeader
        title="Dashboard"
        email={user.email}
        actions={
          <Button variant="ghost" size="sm" onClick={handleSignOut}>
            Sign Out
          </Button>
        }
      />

      <main className="flex-1 mx-auto w-full max-w-6xl px-8 py-8 space-y-6">
        <div className="flex items-center gap-2">
          <h2 className="text-sm font-medium text-muted-foreground">
            {new Date().getHours() < 12
              ? "Good morning"
              : new Date().getHours() < 18
                ? "Good afternoon"
                : "Good evening"
            }, {user.name}
          </h2>
        </div>

        <SectionCards data={cardData} />

        <div className="grid grid-cols-2 gap-4">
          <Link
            to="/account"
            search={{ section: "deposit" }}
            className="inline-flex items-center justify-center gap-3 rounded-xl bg-primary text-primary-foreground h-14 text-sm font-semibold transition-colors hover:opacity-90"
          >
            <Plus className="size-4" />
            Add Money
          </Link>
          <Link
            to="/account?section=transfer"
            className="inline-flex items-center justify-center gap-3 rounded-xl bg-surface text-foreground h-14 text-sm font-semibold transition-colors hover:bg-surface-hover border border-border"
          >
            <ArrowUpRight className="size-4" />
            Send Money
          </Link>
        </div>

        <div>
          <h2 className="text-sm font-medium text-foreground mb-1">Activity</h2>
          <ActivityTimeline
            transactions={transactions}
            accounts={accounts}
            userAccountNumbers={userAccountNumbers}
            loading={loadingTransactions}
            error={null}
            onRetry={fetchTransactions}
          />
        </div>
      </main>

      <PageFooter
        right={
          <span>{accounts.length} account{accounts.length !== 1 ? "s" : ""}</span>
        }
      />
    </>
  )
}

import { useEffect, useState, useMemo, useCallback } from "react"
import {
  useReactTable,
  getCoreRowModel,
  getSortedRowModel,
  flexRender,
  createColumnHelper,
  type SortingState,
} from "@tanstack/react-table"
import { Search } from "lucide-react"
import { signOut, useSession } from "../lib/auth-client"
import { Card, CardContent, CardHeader, CardTitle } from "../components/ui/card"
import { Button } from "../components/ui/button"
import { Input } from "../components/ui/input"
import { Badge } from "../components/ui/badge"
import { Skeleton } from "../components/ui/skeleton"
import PageHeader from "../components/ui/page-header"
import PageFooter from "../components/ui/page-footer"
import { fetchTransactionsAction } from "@/actions/transaction.actions";
import type { ITransaction } from "@/types"
import { formatCurrency } from "@/lib/utils"

interface WalletAccount {
  id: string
  name: string
  userId: string
  accountNumber: string
  balance: number
  createdAt: string
  updatedAt: string | null
}

interface StandardResponse<T = unknown> {
  ok: boolean
  status: number
  message: string
  data?: T
  error?: string
}

type Filter = "all" | "success" | "failed" | "pending"

const formatDate = (iso: string) =>
  new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" }).format(new Date(iso))

export default function TransactionsPage() {
  const { data: session } = useSession()
  const user = session!.user
  const [transactions, setTransactions] = useState<ITransaction[]>([])
  const [accounts, setAccounts] = useState<WalletAccount[]>([])
  const [accountsLoaded, setAccountsLoaded] = useState(false)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [filter, setFilter] = useState<Filter>("all")
  const [searchQuery, setSearchQuery] = useState("")
  const [dateFrom, setDateFrom] = useState("")
  const [dateTo, setDateTo] = useState("")
  const [pageIndex, setPageIndex] = useState(0)
  const [pageSize, setPageSize] = useState(25)
  const [sorting, setSorting] = useState<SortingState>([{ id: "createdAt", desc: true }])

  const columnHelper = createColumnHelper<ITransaction>()

  const userAccountIds = useMemo(() => new Set(accounts.map((a) => a.id)), [accounts])

  const getDirection = useCallback(
    (tx: ITransaction): "in" | "out" | "self" => {
      if (tx.senderName === tx.receiverName) return "self"
      if (userAccountIds.has(tx.receiverAccountNumber.toString()) && !userAccountIds.has(tx.senderAccountNumber.toString())) return "in"
      return "out"
    },
    [userAccountIds],
  )

  const columns = useMemo(
    () => [
      columnHelper.accessor("createdAt", {
        header: "Date",
        cell: (info) => (
          <span className="text-sm text-muted-foreground whitespace-nowrap">
            {formatDate(info.getValue().toString())}
          </span>
        ),
      }),
      columnHelper.display({
        id: "direction",
        header: "",
        cell: ({ row }) => {
          const dir = getDirection(row.original)
          return (
            <div className="shrink-0 w-8 h-8 rounded-full flex items-center justify-center text-sm font-semibold bg-secondary text-secondary-foreground">
              {dir === "in" ? "\u2190" : dir === "self" ? "\u21C4" : "\u2192"}
            </div>
          )
        },
      }),
      columnHelper.accessor("senderName", {
        header: "Counterparty",
        cell: (info) => {
          const tx = info.row.original
          const dir = getDirection(tx)
          const label = dir === "self" ? "Deposit" : dir === "in" ? `From ${tx.senderName}` : `To ${tx.receiverName}`
          return (
            <div className="min-w-0">
              <p className="text-sm font-medium text-foreground truncate">{label}</p>
            </div>
          )
        },
      }),
      columnHelper.accessor("amount", {
        header: "Amount",
        cell: (info) => {
          const tx = info.row.original
          const dir = getDirection(tx)
          return (
            <span className={`text-sm font-mono font-semibold whitespace-nowrap ${
              dir === "in" ? "text-success" : "text-foreground"
            }`}>
              {dir === "in" ? "+" : dir === "out" ? "\u2212" : ""}{formatCurrency(tx.amount)}
            </span>
          )
        },
      }),
      columnHelper.accessor("status", {
        header: "Status",
        cell: (info) => (
          <Badge
            variant={info.getValue() === "success" ? "default" : info.getValue() === "failed" ? "destructive" : "secondary"}
            className="text-[10px] px-1.5 py-0 whitespace-nowrap"
          >
            {info.getValue()}
          </Badge>
        ),
      }),
    ],
    [columnHelper, getDirection],
  )

  const filtered = useMemo(() => {
    let result = transactions

    if (filter !== "all") {
      result = result.filter((tx) => tx.status === filter)
    }

    if (searchQuery.trim()) {
      const q = searchQuery.trim().toLowerCase()
      result = result.filter(
        (tx) =>
          tx.senderName.toLowerCase().includes(q) ||
          tx.receiverName.toLowerCase().includes(q) ||
          tx.senderAccountNumber.toString().includes(q) ||
          tx.receiverAccountNumber.toString().includes(q),
      )
    }

    if (dateFrom) {
      const from = new Date(dateFrom).getTime()
      result = result.filter((tx) => new Date(tx.createdAt).getTime() >= from)
    }

    if (dateTo) {
      const to = new Date(dateTo).getTime() + 86400000
      result = result.filter((tx) => new Date(tx.createdAt).getTime() <= to)
    }

    return result
  }, [transactions, filter, searchQuery, dateFrom, dateTo])

  const totalPages = Math.max(1, Math.ceil(filtered.length / pageSize))
  const paginated = useMemo(() => {
    const start = pageIndex * pageSize
    return filtered.slice(start, start + pageSize)
  }, [filtered, pageIndex, pageSize])

  useEffect(() => {
    setPageIndex(0)
  }, [filter, searchQuery, dateFrom, dateTo])

  const table = useReactTable({
    data: paginated,
    columns,
    state: { sorting },
    onSortingChange: setSorting,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
  })

  const fetchTransactions = useCallback(async () => {
    setLoading(true)
    setError(null)
    try {
      const res = await fetchTransactionsAction(user.id);
      if (!res.ok) throw new Error(res.error ?? `HTTP ${res.status}`)
      const sorted = (res.data ?? []).sort(
        (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
      )
      setTransactions(sorted)
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to load transactions")
      setTransactions([])
    } finally {
      setLoading(false)
    }
  }, [user.id])

  const fetchAccounts = useCallback(async () => {
    try {
      const res = await fetch(`/api/wallet/users/${user.id}/accounts`)
      if (res.ok) {
        const json: StandardResponse<WalletAccount[]> = await res.json()
        setAccounts(json.data ?? [])
      }
    } catch {
      setAccounts([])
    } finally {
      setAccountsLoaded(true)
    }
  }, [user.id])

  useEffect(() => {
    fetchAccounts()
  }, [fetchAccounts])

  useEffect(() => {
    if (accountsLoaded) fetchTransactions()
  }, [user.id, accountsLoaded])

  const handleSignOut = async () => {
    await signOut()
  }

  return (
    <>
      <PageHeader
        title="Transactions"
        email={user.email}
        actions={
          <Button variant="ghost" size="sm" onClick={handleSignOut}>
            Sign Out
          </Button>
        }
      />

      <main className="flex-1 mx-auto w-full max-w-4xl px-8 py-8 space-y-6">
        <div className="flex flex-wrap items-center gap-2">
          {(["all", "success", "pending", "failed"] as const).map((f) => (
            <Button
              key={f}
              variant={filter === f ? "default" : "outline"}
              size="sm"
              onClick={() => setFilter(f)}
              className="capitalize"
            >
              {f}
            </Button>
          ))}

          <div className="flex-1 min-w-[200px] relative">
            <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 size-4 text-muted-foreground pointer-events-none" />
            <Input
              placeholder="Search by name or account..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="pl-8 h-9 text-sm"
            />
          </div>

          <div className="flex items-center gap-2">
            <label className="text-xs text-muted-foreground">From</label>
            <Input
              type="date"
              value={dateFrom}
              onChange={(e) => setDateFrom(e.target.value)}
              className="h-9 w-[140px] text-sm"
            />
            <label className="text-xs text-muted-foreground">To</label>
            <Input
              type="date"
              value={dateTo}
              onChange={(e) => setDateTo(e.target.value)}
              className="h-9 w-[140px] text-sm"
            />
          </div>
        </div>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between pb-4">
            <CardTitle className="text-sm font-medium">
              {filter === "all" ? "All Transactions" : `${filter.charAt(0).toUpperCase() + filter.slice(1)} Transactions`}
            </CardTitle>
            <span className="text-xs text-muted-foreground">{filtered.length} total</span>
          </CardHeader>
          <CardContent className="p-0">
            {loading && (
              <div className="space-y-3 p-6">
                {Array.from({ length: 5 }).map((_, i) => (
                  <Skeleton key={i} className="h-12 w-full rounded-md" />
                ))}
              </div>
            )}

            {error && !loading && (
              <div className="flex flex-col items-center gap-3 py-10 text-center px-6">
                <p className="text-sm text-muted-foreground">{error}</p>
                <Button variant="outline" size="sm" onClick={fetchTransactions}>
                  Retry
                </Button>
              </div>
            )}

            {!loading && !error && filtered.length === 0 && (
              <div className="py-10 text-center px-6">
                <p className="text-sm text-muted-foreground">
                  {transactions.length === 0
                    ? "No transactions yet. Deposit funds to get started."
                    : `No ${filter !== "all" ? filter : ""} transactions found.`}
                </p>
              </div>
            )}

            {!loading && !error && filtered.length > 0 && (
              <>
                <div className="overflow-x-auto">
                  <table className="w-full">
                    <thead>
                      {table.getHeaderGroups().map((hg) => (
                        <tr key={hg.id} className="border-b border-border/50">
                          {hg.headers.map((header) => (
                            <th
                              key={header.id}
                              className="text-left text-xs font-medium text-muted-foreground px-4 py-3 cursor-pointer select-none hover:text-foreground transition-colors"
                              onClick={header.column.getToggleSortingHandler()}
                            >
                              <div className="flex items-center gap-1">
                                {flexRender(header.column.columnDef.header, header.getContext())}
                                {{
                                  asc: " \u25B2",
                                  desc: " \u25BC",
                                }[header.column.getIsSorted() as string] ?? null}
                              </div>
                            </th>
                          ))}
                        </tr>
                      ))}
                    </thead>
                    <tbody>
                      {table.getRowModel().rows.map((row) => (
                        <tr
                          key={row.id}
                          className="cursor-pointer transition-colors hover:bg-surface-hover"
                          onClick={() => window.location.href = `/transactions/${row.original.id}`}
                        >
                          {row.getVisibleCells().map((cell) => (
                            <td key={cell.id} className="px-4 py-3.5 border-b border-border/30 last:border-0">
                              {flexRender(cell.column.columnDef.cell, cell.getContext())}
                            </td>
                          ))}
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
                <div className="flex items-center justify-between px-4 py-3 border-t border-border/50">
                  <div className="flex items-center gap-2">
                    <span className="text-xs text-muted-foreground">Rows per page</span>
                    <select
                      value={pageSize}
                      onChange={(e) => { setPageSize(Number(e.target.value)); setPageIndex(0) }}
                      className="h-8 rounded-md border border-input bg-background px-2 text-xs"
                    >
                      {[10, 25, 50, 100].map((s) => (
                        <option key={s} value={s}>{s}</option>
                      ))}
                    </select>
                  </div>
                  <div className="flex items-center gap-1">
                    <Button
                      variant="outline"
                      size="sm"
                      disabled={pageIndex === 0}
                      onClick={() => setPageIndex((p) => Math.max(0, p - 1))}
                      className="h-8 px-2 text-xs"
                    >
                      Prev
                    </Button>
                    {Array.from({ length: totalPages }, (_, i) => i)
                      .filter((i) => {
                        if (totalPages <= 7) return true
                        if (i === 0 || i === totalPages - 1) return true
                        if (Math.abs(i - pageIndex) <= 1) return true
                        return false
                      })
                      .map((i, idx, arr) => {
                        const showEllipsis = idx > 0 && i - arr[idx - 1] > 1
                        return (
                          <span key={i} className="flex items-center">
                            {showEllipsis && <span className="px-1 text-xs text-muted-foreground">&hellip;</span>}
                            <Button
                              variant={i === pageIndex ? "default" : "outline"}
                              size="sm"
                              onClick={() => setPageIndex(i)}
                              className="h-8 min-w-[28px] px-1 text-xs"
                            >
                              {i + 1}
                            </Button>
                          </span>
                        )
                      })}
                    <Button
                      variant="outline"
                      size="sm"
                      disabled={pageIndex >= totalPages - 1}
                      onClick={() => setPageIndex((p) => Math.min(totalPages - 1, p + 1))}
                      className="h-8 px-2 text-xs"
                    >
                      Next
                    </Button>
                  </div>
                </div>
              </>
            )}
          </CardContent>
        </Card>
      </main>

      <PageFooter
        right={
          <span>{filtered.length} transaction{filtered.length !== 1 ? "s" : ""}</span>
        }
      />
    </>
  )
}

import { useEffect, useState } from "react"
import { useParams, Link } from "@tanstack/react-router"
import { ArrowLeft } from "lucide-react"
import { useSession } from "../lib/auth-client"
import { Card, CardContent, CardHeader, CardTitle } from "../components/ui/card"
import { Badge } from "../components/ui/badge"
import { Skeleton } from "../components/ui/skeleton"
import PageHeader from "../components/ui/page-header"
import PageFooter from "../components/ui/page-footer"
import { fetchTransactionsAction } from "@/actions/transaction.actions"
import { getLedgerEntries } from "@/actions/account.actions"
import type { ITransaction, ILedgerEntry } from "@/types"
import { formatCurrency } from "@/lib/utils"

const formatDate = (iso: string) =>
  new Intl.DateTimeFormat("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  }).format(new Date(iso))

type Direction = "in" | "out" | "self"

export default function TransactionDetailPage() {
  const { data: session } = useSession()
  const user = session!.user
  const params = useParams({ from: "/transactions/$transactionId" })
  const transactionId = params.transactionId

  const [transaction, setTransaction] = useState<ITransaction | null>(null)
  const [accounts, setAccounts] = useState<Set<string>>(new Set())
  const [ledger, setLedger] = useState<ILedgerEntry[]>([])
  const [loading, setLoading] = useState(true)
  const [ledgerLoading, setLedgerLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  const getDirection = (tx: ITransaction): Direction => {
    if (tx.senderName === tx.receiverName) return "self"
    const senderIn = accounts.has(tx.senderAccountNumber.toString())
    const receiverIn = accounts.has(tx.receiverAccountNumber.toString())
    if (receiverIn && !senderIn) return "in"
    return "out"
  }

  useEffect(() => {
    const load = async () => {
      setLoading(true)
      setError(null)
      try {
        const [txRes, accRes] = await Promise.all([
          fetchTransactionsAction(user.id),
          fetch("/api/wallet/users/" + user.id + "/accounts"),
        ])

        const accJson = await accRes.json()
        const accountIds = new Set<string>()
        if (accJson.ok && Array.isArray(accJson.data)) {
          accJson.data.forEach((a: { id: string }) => accountIds.add(a.id))
        }
        setAccounts(accountIds)

        if (!txRes.ok) throw new Error(txRes.error ?? "Failed to load transaction")
        const found = (txRes.data ?? []).find((tx) => tx.id === transactionId)
        if (!found) throw new Error("Transaction not found")
        setTransaction(found)
      } catch (err) {
        setError(err instanceof Error ? err.message : "Failed to load transaction")
      } finally {
        setLoading(false)
      }
    }
    load()
  }, [user.id, transactionId])

  useEffect(() => {
    if (!transaction) return
    setLedgerLoading(true)
    getLedgerEntries(transactionId)
      .then((res) => {
        if (res.ok) setLedger(res.data ?? [])
      })
      .catch(() => {})
      .finally(() => setLedgerLoading(false))
  }, [transaction, transactionId])

  const dir = transaction ? getDirection(transaction) : null

  const detailRow = (label: string, value: string) => (
    <div className="flex items-baseline justify-between gap-4 py-2 border-b border-border/30 last:border-0">
      <span className="text-sm text-muted-foreground shrink-0">{label}</span>
      <span className="text-sm font-medium text-foreground text-right font-mono break-all">{value}</span>
    </div>
  )

  return (
    <>
      <PageHeader
        title={loading ? <Skeleton className="h-6 w-40" /> : "Transaction Details"}
        email={user.email}
        beforeTitle={
          <Link
            to="/transactions"
            className="inline-flex items-center justify-center w-8 h-8 rounded-md text-muted-foreground hover:text-foreground hover:bg-muted transition-colors"
            aria-label="Back to Transactions"
          >
            <ArrowLeft className="size-4" />
          </Link>
        }
      />

      <main className="flex-1 mx-auto w-full max-w-2xl px-8 py-8 space-y-6">
        {loading && (
          <Card>
            <CardContent className="p-6 space-y-4">
              <Skeleton className="h-4 w-24" />
              <Skeleton className="h-10 w-48" />
              <Skeleton className="h-4 w-36" />
              <Skeleton className="h-4 w-56" />
              <Skeleton className="h-4 w-40" />
            </CardContent>
          </Card>
        )}

        {error && !loading && (
          <div className="flex flex-col items-center gap-3 py-10 text-center">
            <p className="text-sm text-muted-foreground">{error}</p>
            <Link to="/transactions">
              <span className="inline-flex items-center justify-center rounded-md bg-primary text-primary-foreground h-9 px-4 text-sm font-medium">Back to Transactions</span>
            </Link>
          </div>
        )}

        {!loading && !error && transaction && (
          <>
            <Card>
              <CardContent className="p-6 space-y-5">
                <div className="flex items-start justify-between">
                  <div className="space-y-1">
                    <p className="text-xs font-medium text-muted-foreground uppercase tracking-wider">Amount</p>
                    <p className={`text-3xl font-semibold font-mono tracking-tight ${
                      dir === "in" ? "text-success" : "text-foreground"
                    }`}>
                      {dir === "in" ? "+" : dir === "out" ? "\u2212" : ""}
                      {formatCurrency(transaction.amount)}
                    </p>
                  </div>
                  <Badge
                    variant={transaction.status === "success" ? "default" : transaction.status === "failed" ? "destructive" : "secondary"}
                    className="text-xs"
                  >
                    {transaction.status}
                  </Badge>
                </div>

                <div className="pt-2 border-t border-border/50 space-y-0">
                  <div className="grid grid-cols-2 gap-4 pb-4 border-b border-border/30">
                    <div className="space-y-1">
                      <p className="text-xs text-muted-foreground">From</p>
                      <p className="text-sm font-medium text-foreground">{transaction.senderName}</p>
                      <p className="text-xs font-mono text-muted-foreground">{String(transaction.senderAccountNumber)}</p>
                    </div>
                    <div className="space-y-1">
                      <p className="text-xs text-muted-foreground">To</p>
                      <p className="text-sm font-medium text-foreground">{transaction.receiverName}</p>
                      <p className="text-xs font-mono text-muted-foreground">{String(transaction.receiverAccountNumber)}</p>
                    </div>
                  </div>

                  {detailRow("Transaction ID", transaction.id)}
                  {detailRow("Created", formatDate(transaction.createdAt))}
                  {transaction.updatedAt && detailRow("Updated", formatDate(transaction.updatedAt))}
                  {detailRow("Type", dir === "self" ? "Deposit" : dir === "in" ? "Incoming Transfer" : "Outgoing Transfer")}
                </div>
              </CardContent>
            </Card>

            <Card>
              <CardHeader>
                <CardTitle className="text-sm font-medium">Ledger Entries</CardTitle>
              </CardHeader>
              <CardContent className="p-0">
                {ledgerLoading && (
                  <div className="space-y-3 p-6">
                    {Array.from({ length: 2 }).map((_, i) => (
                      <Skeleton key={i} className="h-10 w-full rounded-md" />
                    ))}
                  </div>
                )}
                {!ledgerLoading && ledger.length === 0 && (
                  <div className="py-8 text-center px-6">
                    <p className="text-sm text-muted-foreground">No ledger entries available.</p>
                  </div>
                )}
                {!ledgerLoading && ledger.length > 0 && (
                  <div className="divide-y divide-border/30">
                    {ledger.map((entry) => (
                      <div key={entry.id} className="flex items-center justify-between px-6 py-3.5">
                        <div className="flex items-center gap-3">
                          <div className={`w-2 h-2 rounded-full ${
                            entry.entryType === "debit" ? "bg-destructive" : "bg-success"
                          }`} />
                          <span className="text-sm font-medium text-foreground capitalize">{entry.entryType}</span>
                        </div>
                        <span className="text-sm font-mono text-foreground">{formatCurrency(entry.amount)}</span>
                      </div>
                    ))}
                  </div>
                )}
              </CardContent>
            </Card>
          </>
        )}
      </main>

      <PageFooter
        right={transaction && <span>ID: {transaction.id.slice(0, 8)}&hellip;</span>}
      />
    </>
  )
}

import { useEffect, useState, useCallback } from "react"
import { useSearch } from "@tanstack/react-router"
import { MoreVertical } from "lucide-react"
import { signOut, useSession } from "../lib/auth-client"
import { Card, CardContent, CardHeader, CardTitle } from "../components/ui/card"
import { Button } from "../components/ui/button"
import { Input } from "../components/ui/input"
import { Label } from "../components/ui/label"
import { Select } from "../components/ui/select"
import { Skeleton } from "../components/ui/skeleton"
import {
  DropdownMenu,
  DropdownMenuTrigger,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
} from "../components/ui/dropdown-menu"
import ProfileSection from "../components/ProfileSection"
import WalletCardCarousel from "../components/WalletCardCarousel"
import { formatCurrency } from "@/lib/utils"
import type { IWalletTransaction, WaveResponse, ITransaction, TBankAccountNumber } from "@/types"
import { createAccount, fetchAccountData } from "@/actions/account.actions"
import AddMoney from "../components/AddMoney"
import TransactionSuccess from "../components/ui/transaction-success"
import ProcessingOverlay from "../components/ui/processing-overlay"
import PageHeader from "../components/ui/page-header"
import PageFooter from "../components/ui/page-footer"

export default function AccountPage() {
  const { data: session } = useSession()
  const user = session!.user
  const search = useSearch({ strict: false }) as { section?: string }
  const initialSection = search.section ?? null

  const [accounts, setAccounts] = useState<IWalletTransaction[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [creating, setCreating] = useState(false)
  const [createError, setCreateError] = useState<string | null>(null)
  const [accountName, setAccountName] = useState("")

  const [transferring, setTransferring] = useState(false);
  const [transferError, setTransferError] = useState<string | null>(null);
  const [transferSuccess, setTransferSuccess] = useState<ITransaction | null>(null);
  const [senderAccountNumber, setSenderAccountNumber] = useState<TBankAccountNumber>();
  const [receiverNumber, setReceiverNumber] = useState("")
  const [amount, setAmount] = useState("")
  const [receiverLookup, setReceiverLookup] = useState<{ name: string; accountNumber: TBankAccountNumber } | null>(null)
  const [lookingUp, setLookingUp] = useState(false)

  const fetchAccounts = useCallback(async () => {
    try {
      setLoading(true)
      setError(null)

      const res = await fetchAccountData(user.id);
      if(!res.ok) {
        setAccounts([])
        setError(res.message || "Failed to load accounts")

        return;
      }

      setAccounts(res.data);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to load accounts")
      setAccounts([])
    } finally {
      setLoading(false);
    }
  }, [user.id])

  useEffect(() => {
    fetchAccounts()
  }, [fetchAccounts])

  useEffect(() => {
    if (initialSection === "deposit" || initialSection === "transfer") {
      const id = initialSection === "deposit" ? "deposit-section" : "transfer-section"
      const el = document.getElementById(id)
      if (el) el.scrollIntoView({ behavior: "smooth" })
    }
  }, [initialSection])

  useEffect(() => {
    if (!receiverNumber.trim() || receiverNumber.length < 8) {
      setReceiverLookup(null)
      return
    }
    const timer = setTimeout(async () => {
      setLookingUp(true)
      try {
        const res = await fetch(`/api/wallet/accounts/by-number/${encodeURIComponent(receiverNumber.trim())}`)
        const json: WaveResponse<IWalletTransaction> = await res.json()
        if (json.ok) {
          setReceiverLookup({
            accountNumber: json.data.accountNumber,
            name: json.data.name,
          })
        }
      } catch {
        setReceiverLookup(null)
      } finally {
        setLookingUp(false)
      }
    }, 400)
    return () => clearTimeout(timer)
  }, [receiverNumber])

  const handleCreateAccount = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!accountName.trim()) return

    setCreating(true)
    setCreateError(null)

    const accountNumber = String(Math.floor(Math.random() * 9_000_000_000_000) + 1_000_000_000_000) as unknown as TBankAccountNumber;

    try {
      const res = await createAccount({
        userId: user.id,
        name: accountName.trim(),
        accountNumber,
        balance: 0,
      });

      if (!res.ok) {
        throw new Error(res.error ?? `HTTP ${res.status}`)
      }
      setAccounts((prev) => [...prev, res.data])
      setAccountName("")
    } catch (err) {
      setCreateError(err instanceof Error ? err.message : "Failed to create account")
    } finally {
      setCreating(false)
    }
  }

  const handleTransfer = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!senderAccountNumber || !receiverLookup || !amount.trim()) return

    setTransferring(true)
    setTransferError(null)
    setTransferSuccess(null)

    const sender = accounts.find((a) => a.accountNumber === senderAccountNumber)

    try {
      const res = await fetch("/api/wallet/transfers", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          userId: user.id,
          senderAccountNumber: senderAccountNumber,
          senderName: sender?.name ?? "Unknown",
          receiverAccountNumber: receiverLookup.accountNumber,
          receiverName: receiverLookup.name,
          amount: Number.parseFloat(amount),
        }),
      })
      const json: WaveResponse<ITransaction> = await res.json()
      if (!json.ok) throw new Error(json.error ?? `HTTP ${res.status}`)
      setTransferSuccess(json.data)
      setSenderAccountNumber(json.data.senderAccountNumber)
      setReceiverNumber("")
      setAmount("")
      setReceiverLookup(null)
      fetchAccounts()
    } catch (err) {
      setTransferError(err instanceof Error ? err.message : "Failed to send transfer")
    } finally {
      setTransferring(false)
    }
  }



  const handleSignOut = async () => {
    await signOut()
  }

  return (
    <>
      <PageHeader
        title="Account"
        email={user.email}
        actions={
          <>
            <Button variant="outline" size="sm" onClick={fetchAccounts} disabled={loading}>
              Refresh
            </Button>
            <DropdownMenu>
              <DropdownMenuTrigger className="flex items-center justify-center w-8 h-8 rounded-md border border-input bg-background hover:bg-accent hover:text-accent-foreground">
                <MoreVertical className="size-4" />
              </DropdownMenuTrigger>
              <DropdownMenuContent>
                <DropdownMenuItem onClick={() => window.location.href = "/account/settings"}>
                  Edit
                </DropdownMenuItem>
                <DropdownMenuSeparator />
                <DropdownMenuItem onClick={() => window.location.href = "/account/transactions"}>
                  Transactions
                </DropdownMenuItem>
                <DropdownMenuSeparator />
                <DropdownMenuItem onClick={handleSignOut}>
                  Sign Out
                </DropdownMenuItem>
              </DropdownMenuContent>
            </DropdownMenu>
          </>
        }
      />

      <main className="grid grid-cols-2 gap-6 mx-auto w-full px-8 py-8 space-y-6">
        <div className="space-y-6 flex flex-col px-6 w-full mx-auto">
          <ProfileSection />

          <Card className="w-full mx-auto">
            <CardHeader className="flex flex-row items-center justify-between">
              <CardTitle>Wallet Accounts</CardTitle>
              <span className="text-xs text-muted-foreground">{accounts.length} total</span>
            </CardHeader>
            <CardContent className="space-y-3 w-full">
              {loading && (
                <div className="space-y-3">
                  {Array.from({ length: 2 }).map((_, i) => (
                    <Skeleton key={i} className="h-16 w-full rounded-lg" />
                  ))}
                </div>
              )}

              {error && !loading && (
                <div className="flex flex-col items-center gap-3 py-6 text-center">
                  <p className="text-sm text-muted-foreground">{error}</p>
                  <Button variant="outline" size="sm" onClick={fetchAccounts}>
                    Retry
                  </Button>
                </div>
              )}

              {!loading && !error && accounts.length === 0 && (
                <div className="py-6 text-center">
                  <p className="text-sm text-muted-foreground">No accounts yet. Create one below.</p>
                </div>
              )}

              {!loading && !error && accounts.length > 0 && (
                <WalletCardCarousel accounts={accounts} />
              )}

              <form onSubmit={handleCreateAccount} className="space-y-3 pt-4 border-t border-border">
                <div className="space-y-1.5">
                  <Label htmlFor="account-name">New Account Name</Label>
                  <Input
                    id="account-name"
                    placeholder="e.g. Checking, Savings"
                    value={accountName}
                    onChange={(e) => setAccountName(e.target.value)}
                    disabled={creating}
                  />
                </div>
                {createError && (
                  <p className="text-sm text-destructive">{createError}</p>
                )}
                <Button type="submit" disabled={creating || !accountName.trim()} className="w-full">
                  {creating ? "Creating..." : "Create Account"}
                </Button>
              </form>
            </CardContent>
          </Card>
        </div>

        <div className="space-y-6 flex flex-col px-6 w-full mx-auto">
          <AddMoney accounts={accounts} userId={user.id} onDeposit={fetchAccounts} />

          <Card id="transfer-section" className="max-w-md mx-auto">
            <CardHeader>
              <CardTitle>Send Money</CardTitle>
            </CardHeader>
            <CardContent>
              {transferSuccess ? (
                <TransactionSuccess
                  title="Transfer completed"
                  amount={formatCurrency(transferSuccess.amount)}
                  description={`${transferSuccess.senderName} \u2192 ${transferSuccess.receiverName}`}
                  actionLabel="Send another"
                  onReset={() => setTransferSuccess(null)}
                />
              ) : (
                <form onSubmit={handleTransfer} className="space-y-4">
                  <div className="space-y-1.5">
                    <Label htmlFor="sender">From</Label>
                    <Select
                      id="sender"
                      value={senderAccountNumber as unknown as number}
                      onChange={(e) => setSenderAccountNumber(e.target.value as unknown as TBankAccountNumber)}
                      required
                    >
                      <option value="" disabled>Select an account</option>
                      {accounts.map((acc) => (
                        <option key={acc.id} value={acc.accountNumber as unknown as number}>
                          {acc.name} ({acc.accountNumber}) · {formatCurrency(acc.balance)}
                        </option>
                      ))}
                    </Select>
                  </div>

                  <div className="space-y-1.5">
                    <Label htmlFor="receiver">To (account number)</Label>
                    <Input
                      id="receiver"
                      placeholder="e.g. 1000000000000"
                      value={receiverNumber}
                      onChange={(e) => setReceiverNumber(e.target.value)}
                    />
                    {lookingUp && (
                      <p className="text-xs text-muted-foreground">Looking up account...</p>
                    )}
                    {receiverLookup && !lookingUp && (
                      <p className="text-xs font-medium text-success">{receiverLookup.name}</p>
                    )}
                    {!receiverLookup && !lookingUp && receiverNumber.length >= 8 && (
                      <p className="text-xs text-muted-foreground">No account found with that number</p>
                    )}
                  </div>

                  <div className="space-y-1.5">
                    <Label htmlFor="amount">Amount (USD)</Label>
                    <Input
                      id="amount"
                      type="number"
                      step="0.01"
                      min="0.01"
                      placeholder="0.00"
                      value={amount}
                      onChange={(e) => setAmount(e.target.value)}
                    />
                  </div>

                  {transferError && (
                    <p className="text-sm text-destructive">{transferError}</p>
                  )}

                  <Button
                    type="submit"
                    disabled={!senderAccountNumber || !receiverLookup || !amount.trim() || Number(amount) <= 0}
                    className="w-full"
                  >
                    Send Money
                  </Button>
                </form>
              )}
            </CardContent>
          </Card>
        </div>
      </main>

      <PageFooter right={<span>{accounts.length} account{accounts.length !== 1 ? "s" : ""}</span>} />

      {transferring && (
        <ProcessingOverlay
          amount={formatCurrency(amount)}
          description={`${accounts.find((a) => a.accountNumber === senderAccountNumber)?.name ?? "Sender"} \u2192 ${receiverLookup?.name ?? "Receiver"}`}
          label="Processing transfer"
        />
      )}
    </>
  )
}

import { useEffect, useState, useCallback, useMemo } from "react"
import { useParams, Link } from "@tanstack/react-router"
import { ArrowLeft, Eye, EyeOff, MoreVertical } from "lucide-react"
import { useSession } from "../lib/auth-client"
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
} from "../components/ui/card"
import { Button } from "../components/ui/button"
import { Badge } from "../components/ui/badge"
import { Skeleton } from "../components/ui/skeleton"
import {
  DropdownMenu,
  DropdownMenuTrigger,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
} from "../components/ui/dropdown-menu"
import PageHeader from "../components/ui/page-header"
import PageFooter from "../components/ui/page-footer"
import { fetchAccountData } from "@/actions/account.actions"
import { fetchTransactionsAction } from "@/actions/transaction.actions"
import type { IWalletTransaction, ITransaction, WaveResponse } from "@/types"
import { formatCurrency } from "@/lib/utils"

const formatDate = (iso: string) =>
  new Intl.DateTimeFormat("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  }).format(new Date(iso))

type Direction = "in" | "out" | "self"

export default function AccountDetailPage() {
  const { data: session } = useSession()
  const user = session!.user
  const params = useParams({ from: "/account/$accountNumber" })
  const accountNumberParam = params.accountNumber

  const [accounts, setAccounts] = useState<IWalletTransaction[]>([])
  const [transactions, setTransactions] = useState<ITransaction[]>([])
  const [loading, setLoading] = useState(true)
  const [transactionsLoading, setTransactionsLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [showBalance, setShowBalance] = useState(true)

  const account = useMemo(
    () => accounts.find((a) => String(a.accountNumber) === accountNumberParam) ?? null,
    [accounts, accountNumberParam],
  )

  const getDirection = useCallback(
    (tx: ITransaction): Direction => {
      const txSender = String(tx.senderAccountNumber)
      const txReceiver = String(tx.receiverAccountNumber)
      if (txSender === txReceiver) return "self"
      if (txReceiver === accountNumberParam) return "in"
      if (txSender === accountNumberParam) return "out"
      return "out"
    },
    [accountNumberParam],
  )

  const accountTransactions = useMemo(
    () =>
      transactions.filter((tx) => {
        const sender = String(tx.senderAccountNumber)
        const receiver = String(tx.receiverAccountNumber)
        return sender === accountNumberParam || receiver === accountNumberParam
      }),
    [transactions, accountNumberParam],
  )

  const recentTransactions = useMemo(() => accountTransactions.slice(0, 10), [accountTransactions])

  const fetchAccounts = useCallback(async () => {
    try {
      setLoading(true)
      setError(null)
      const res = await fetchAccountData(user.id)
      if (!res.ok) {
        setError(res.error ?? "Failed to load account")
        return
      }
      setAccounts(res.data)
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to load account")
    } finally {
      setLoading(false)
    }
  }, [user.id])

  const fetchTransactions = useCallback(async () => {
    setTransactionsLoading(true)
    try {
      const res = await fetchTransactionsAction(user.id)
      if (res.ok) {
        const sorted = (res.data ?? []).sort(
          (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime(),
        )
        setTransactions(sorted)
      }
    } catch {
      // silently fail for transactions
    } finally {
      setTransactionsLoading(false)
    }
  }, [user.id])

  useEffect(() => {
    fetchAccounts()
    fetchTransactions()
  }, [fetchAccounts, fetchTransactions])

  const pageTitle = account?.name ?? "Account Details"

  return (
    <>
      <PageHeader
        title={loading ? <Skeleton className="h-6 w-40" /> : pageTitle}
        email={user.email}
        beforeTitle={
          <Link
            to="/account"
            className="inline-flex items-center justify-center w-8 h-8 rounded-md text-muted-foreground hover:text-foreground hover:bg-muted transition-colors"
            aria-label="Back to Account"
          >
            <ArrowLeft className="size-4" />
          </Link>
        }
        actions={
          account && (
            <DropdownMenu>
              <DropdownMenuTrigger className="w-8 h-8 border border-input bg-background">
                <MoreVertical className="size-4" />
              </DropdownMenuTrigger>
              <DropdownMenuContent>
                <DropdownMenuItem onClick={() => window.location.href = "/account/settings"}>
                  Edit
                </DropdownMenuItem>
                <DropdownMenuSeparator />
                <DropdownMenuItem onClick={() => window.location.href = "/account/transactions"}>
                  All Transactions
                </DropdownMenuItem>
              </DropdownMenuContent>
            </DropdownMenu>
          )
        }
      />

          <main className="flex-1 mx-auto w-full max-w-2xl px-8 py-8 space-y-6">
            {error && !loading && (
              <div className="flex flex-col items-center gap-3 py-10 text-center">
                <p className="text-sm text-muted-foreground">{error}</p>
                <Button variant="outline" size="sm" onClick={fetchAccounts}>
                  Retry
                </Button>
              </div>
            )}

            {loading && (
              <Card>
                <CardContent className="p-6 space-y-4">
                  <Skeleton className="h-4 w-24" />
                  <Skeleton className="h-10 w-48" />
                  <Skeleton className="h-4 w-36" />
                  <Skeleton className="h-4 w-56" />
                </CardContent>
              </Card>
            )}

            {!loading && !error && account && (
              <>
                <Card>
                  <CardContent className="p-6 space-y-5">
                    <div className="flex items-start justify-between">
                      <div className="space-y-1">
                        <p className="text-xs font-medium text-muted-foreground uppercase tracking-wider">
                          Current Balance
                        </p>
                        <div className="flex items-center gap-2">
                          <p
                            className={`text-3xl font-semibold font-mono tracking-tight transition-all duration-300 ${
                              !showBalance ? "blur-lg select-none" : ""
                            }`}
                            aria-hidden={!showBalance}
                          >
                            {formatCurrency(account.balance)}
                          </p>
                          <button
                            type="button"
                            onClick={() => setShowBalance((v) => !v)}
                            className="flex items-center justify-center w-8 h-8 rounded-md text-muted-foreground hover:text-foreground hover:bg-muted transition-colors"
                            aria-label={showBalance ? "Hide balance" : "Show balance"}
                          >
                            {showBalance ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
                          </button>
                        </div>
                      </div>
                      <Badge variant="secondary" className="text-xs">
                        Active
                      </Badge>
                    </div>

                    <div className="grid grid-cols-2 gap-4 pt-2 border-t border-border/50">
                      <div className="space-y-1">
                        <p className="text-xs text-muted-foreground">Account Number</p>
                        <p className="text-sm font-mono text-foreground">
                          {String(account.accountNumber)}
                        </p>
                      </div>
                      <div className="space-y-1">
                        <p className="text-xs text-muted-foreground">Created</p>
                        <p className="text-sm text-foreground">
                          {formatDate(String(account.createdAt))}
                        </p>
                      </div>
                      <div className="space-y-1">
                        <p className="text-xs text-muted-foreground">Account Name</p>
                        <p className="text-sm text-foreground">{account.name}</p>
                      </div>
                      <div className="space-y-1">
                        <p className="text-xs text-muted-foreground">Monthly Volume</p>
                        <p className="text-sm text-foreground">
                          {formatCurrency(accountTransactions.reduce((sum, tx) => sum + Number(tx.amount), 0))}
                        </p>
                      </div>
                    </div>
                  </CardContent>
                </Card>

                <div className="grid grid-cols-2 gap-4">
                  <Link
                    to="/account"
                    search={{ section: "deposit" }}
                    className="inline-flex items-center justify-center gap-2 rounded-xl bg-primary text-primary-foreground h-12 text-sm font-semibold transition-colors hover:opacity-90"
                  >
                    Add Money
                  </Link>
                  <Link
                    to="/account"
                    className="inline-flex items-center justify-center gap-2 rounded-xl bg-surface text-foreground h-12 text-sm font-semibold transition-colors hover:bg-surface-hover border border-border"
                  >
                    Send Money
                  </Link>
                </div>

                <Card>
                  <CardHeader className="flex flex-row items-center justify-between pb-4">
                    <CardTitle className="text-sm font-medium">
                      Recent Transactions
                    </CardTitle>
                    <Link
                      to="/account/transactions"
                      className="text-sm font-medium text-muted-foreground hover:text-foreground transition-colors"
                    >
                      View all
                    </Link>
                  </CardHeader>
                  <CardContent className="p-0">
                    {transactionsLoading && (
                      <div className="space-y-3 p-6">
                        {Array.from({ length: 4 }).map((_, i) => (
                          <Skeleton key={i} className="h-12 w-full rounded-md" />
                        ))}
                      </div>
                    )}

                    {!transactionsLoading && recentTransactions.length === 0 && (
                      <div className="py-10 text-center px-6">
                        <p className="text-sm text-muted-foreground">
                          No transactions yet for this account.
                        </p>
                      </div>
                    )}

                    {!transactionsLoading && recentTransactions.length > 0 && (
                      <div className="divide-y divide-border/30">
                        {recentTransactions.map((tx) => {
                          const dir = getDirection(tx)
                          const amount = Number(tx.amount)
                          return (
                            <div
                              key={tx.id}
                              className="flex items-center gap-4 px-6 py-4 transition-colors hover:bg-surface-hover cursor-pointer"
                              onClick={() => window.location.href = `/transactions/${tx.id}`}
                            >
                              <div className="shrink-0 w-9 h-9 rounded-full flex items-center justify-center text-sm font-semibold bg-secondary text-secondary-foreground">
                                {dir === "in" ? "\u2190" : dir === "self" ? "\u21C4" : "\u2192"}
                              </div>
                              <div className="flex-1 min-w-0">
                                <p className="text-sm font-medium text-foreground truncate">
                                  {dir === "self"
                                    ? "Deposit"
                                    : dir === "in"
                                      ? `From ${tx.senderName}`
                                      : `To ${tx.receiverName}`}
                                </p>
                                <p className="text-xs text-muted-foreground">
                                  {formatDate(tx.createdAt)}
                                </p>
                              </div>
                              <div className="text-right">
                                <p
                                  className={`text-sm font-mono font-semibold whitespace-nowrap ${
                                    dir === "in" ? "text-success" : "text-foreground"
                                  }`}
                                >
                                  {dir === "in" ? "+" : dir === "out" ? "\u2212" : ""}
                                  {formatCurrency(amount)}
                                </p>
                                <Badge
                                  variant={
                                    tx.status === "success"
                                      ? "default"
                                      : tx.status === "failed"
                                        ? "destructive"
                                        : "secondary"
                                  }
                                  className="text-[10px] px-1.5 py-0 mt-0.5"
                                >
                                  {tx.status}
                                </Badge>
                              </div>
                            </div>
                          )
                        })}
                      </div>
                    )}
                  </CardContent>
                </Card>
              </>
            )}

            {!loading && !error && !account && (
              <div className="flex flex-col items-center gap-3 py-10 text-center">
                <p className="text-sm text-muted-foreground">Account not found.</p>
                <Link to="/account">
                  <Button variant="outline" size="sm">
                    Back to Accounts
                  </Button>
                </Link>
              </div>
            )}
          </main>

      <PageFooter
        right={
          <span>
            {accountTransactions.length} transaction{accountTransactions.length !== 1 ? "s" : ""}
          </span>
        }
      />
    </>
  )
}

import { useEffect, useState, useMemo, useCallback } from "react"
import {
  useReactTable,
  getCoreRowModel,
  getSortedRowModel,
  flexRender,
  createColumnHelper,
  type SortingState,
} from "@tanstack/react-table"
import { ArrowLeft, Search } from "lucide-react"
import { useSession } from "../lib/auth-client"
import { Card, CardContent, CardHeader, CardTitle } from "../components/ui/card"
import { Button } from "../components/ui/button"
import { Input } from "../components/ui/input"
import { Badge } from "../components/ui/badge"
import { Skeleton } from "../components/ui/skeleton"
import PageHeader from "../components/ui/page-header"
import PageFooter from "../components/ui/page-footer"
import { fetchTransactionsAction } from "@/actions/transaction.actions"
import type { ITransaction, IWalletTransaction, WaveResponse } from "@/types"
import { fetchAccountTransactionsAction } from "@/actions/account.actions"
import { formatCurrency } from "@/lib/utils"

type Filter = "all" | "success" | "failed" | "pending"

const formatDate = (iso: string) =>
  new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" }).format(new Date(iso))

export default function AccountTransactionsPage() {
  const { data: session } = useSession()
  const user = session!.user
  const [transactions, setTransactions] = useState<ITransaction[]>([])
  const [accounts, setAccounts] = useState<IWalletTransaction[]>([])
  const [accountsLoaded, setAccountsLoaded] = useState(false)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [filter, setFilter] = useState<Filter>("all")
  const [searchQuery, setSearchQuery] = useState("")
  const [dateFrom, setDateFrom] = useState("")
  const [dateTo, setDateTo] = useState("")
  const [pageIndex, setPageIndex] = useState(0)
  const [pageSize, setPageSize] = useState(25)
  const [sorting, setSorting] = useState<SortingState>([{ id: "createdAt", desc: true }])

  const columnHelper = createColumnHelper<ITransaction>()

  const userAccountIds = useMemo(() => new Set(accounts.map((a) => a.id)), [accounts])

  const getDirection = useCallback(
    (tx: ITransaction): "in" | "out" | "self" => {
      if (tx.senderName === tx.receiverName) return "self"
      if (userAccountIds.has(tx.senderAccountNumber.toString())) return "in"
      if (userAccountIds.has(tx.receiverAccountNumber.toString())) return "in"
      return "out"
    },
    [userAccountIds],
  )

  const columns = useMemo(
    () => [
      columnHelper.accessor("createdAt", {
        header: "Date",
        cell: (info) => (
          <span className="text-sm text-muted-foreground whitespace-nowrap">
            {formatDate(info.getValue().toString())}
          </span>
        ),
      }),
      columnHelper.display({
        id: "direction",
        header: "",
        cell: ({ row }) => {
          const dir = getDirection(row.original)
          return (
            <div className="shrink-0 w-8 h-8 rounded-full flex items-center justify-center text-sm font-semibold bg-secondary text-secondary-foreground">
              {dir === "in" ? "\u2190" : dir === "self" ? "\u21C4" : "\u2192"}
            </div>
          )
        },
      }),
      columnHelper.accessor("senderName", {
        header: "Counterparty",
        cell: (info) => {
          const tx = info.row.original
          const dir = getDirection(tx)
          const label = dir === "self" ? "Deposit" : dir === "in" ? `From ${tx.senderName}` : `To ${tx.receiverName}`
          return (
            <div className="min-w-0">
              <p className="text-sm font-medium text-foreground truncate">{label}</p>
            </div>
          )
        },
      }),
      columnHelper.accessor("amount", {
        header: "Amount",
        cell: (info) => {
          const tx = info.row.original
          const dir = getDirection(tx)
          return (
            <span className={`text-sm font-mono font-semibold whitespace-nowrap ${
              dir === "in" ? "text-success" : "text-foreground"
            }`}>
              {dir === "in" ? "+" : dir === "out" ? "\u2212" : ""}{formatCurrency(tx.amount)}
            </span>
          )
        },
      }),
      columnHelper.accessor("status", {
        header: "Status",
        cell: (info) => (
          <Badge
            variant={info.getValue() === "success" ? "default" : info.getValue() === "failed" ? "destructive" : "secondary"}
            className="text-[10px] px-1.5 py-0 whitespace-nowrap"
          >
            {info.getValue()}
          </Badge>
        ),
      }),
    ],
    [columnHelper, getDirection],
  )

  const filtered = useMemo(() => {
    let result = transactions

    if (filter !== "all") {
      result = result.filter((tx) => tx.status === filter)
    }

    if (searchQuery.trim()) {
      const q = searchQuery.trim().toLowerCase()
      result = result.filter(
        (tx) =>
          tx.senderName.toLowerCase().includes(q) ||
          tx.receiverName.toLowerCase().includes(q) ||
          tx.senderAccountNumber.toString().includes(q) ||
          tx.receiverAccountNumber.toString().includes(q),
      )
    }

    if (dateFrom) {
      const from = new Date(dateFrom).getTime()
      result = result.filter((tx) => new Date(tx.createdAt).getTime() >= from)
    }

    if (dateTo) {
      const to = new Date(dateTo).getTime() + 86400000
      result = result.filter((tx) => new Date(tx.createdAt).getTime() <= to)
    }

    return result
  }, [transactions, filter, searchQuery, dateFrom, dateTo])

  const totalPages = Math.max(1, Math.ceil(filtered.length / pageSize))
  const paginated = useMemo(() => {
    const start = pageIndex * pageSize
    return filtered.slice(start, start + pageSize)
  }, [filtered, pageIndex, pageSize])

  useEffect(() => {
    setPageIndex(0)
  }, [filter, searchQuery, dateFrom, dateTo])

  const table = useReactTable({
    data: paginated,
    columns,
    state: { sorting },
    onSortingChange: setSorting,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
  })

  const fetchTransactions = useCallback(async () => {
    setLoading(true)
    setError(null)
    try {
      const res = await fetchTransactionsAction(user.id);
      if (!res.ok) throw new Error(res.error ?? `HTTP ${res.status}`)

      const sorted = (res.data ?? []).sort(
        (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
      )
      setTransactions(sorted)
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to load transactions")
      setTransactions([])
    } finally {
      setLoading(false)
    }
  }, [user.id])

  const fetchAccounts = useCallback(async () => {
    try {
      const res = await fetchAccountTransactionsAction(user.id); 
      if (!res.ok) {
        throw new Error(res.error ?? `HTTP ${res.status}`)
      };

      setAccounts(res.data)
    } catch (error) {
      console.error("Error fetching account data:", error)
      setAccounts([])
    } finally {
      setAccountsLoaded(true)
    }
  }, [user.id])

  useEffect(() => {
    fetchAccounts()
  }, [fetchAccounts])

  useEffect(() => {
    if (accountsLoaded) fetchTransactions()
  }, [user.id, accountsLoaded])

  return (
    <>
      <PageHeader
        title="Transactions"
        email={user.email}
        beforeTitle={
          <a
            href="/account"
            className="inline-flex items-center justify-center w-8 h-8 rounded-md text-muted-foreground hover:text-foreground hover:bg-muted transition-colors"
            aria-label="Back to Account"
          >
            <ArrowLeft className="size-4" />
          </a>
        }
      />

      <main className="flex-1 mx-auto w-full max-w-4xl px-8 py-8 space-y-6">
        <div className="flex flex-wrap items-center gap-2">
          {(["all", "success", "pending", "failed"] as const).map((f) => (
            <Button
              key={f}
              variant={filter === f ? "default" : "outline"}
              size="sm"
              onClick={() => setFilter(f)}
              className="capitalize"
            >
              {f}
            </Button>
          ))}

          <div className="flex-1 min-w-[200px] relative">
            <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 size-4 text-muted-foreground pointer-events-none" />
            <Input
              placeholder="Search by name or account..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="pl-8 h-9 text-sm"
            />
          </div>

          <div className="flex items-center gap-2">
            <label className="text-xs text-muted-foreground">From</label>
            <Input
              type="date"
              value={dateFrom}
              onChange={(e) => setDateFrom(e.target.value)}
              className="h-9 w-[140px] text-sm"
            />
            <label className="text-xs text-muted-foreground">To</label>
            <Input
              type="date"
              value={dateTo}
              onChange={(e) => setDateTo(e.target.value)}
              className="h-9 w-[140px] text-sm"
            />
          </div>
        </div>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between pb-4">
            <CardTitle className="text-sm font-medium">
              {filter === "all" ? "All Transactions" : `${filter.charAt(0).toUpperCase() + filter.slice(1)} Transactions`}
            </CardTitle>
            <span className="text-xs text-muted-foreground">{filtered.length} total</span>
          </CardHeader>
          <CardContent className="p-0">
            {loading && (
              <div className="space-y-3 p-6">
                {Array.from({ length: 5 }).map((_, i) => (
                  <Skeleton key={i} className="h-12 w-full rounded-md" />
                ))}
              </div>
            )}

            {error && !loading && (
              <div className="flex flex-col items-center gap-3 py-10 text-center px-6">
                <p className="text-sm text-muted-foreground">{error}</p>
                <Button variant="outline" size="sm" onClick={fetchTransactions}>
                  Retry
                </Button>
              </div>
            )}

            {!loading && !error && filtered.length === 0 && (
              <div className="py-10 text-center px-6">
                <p className="text-sm text-muted-foreground">
                  {transactions.length === 0
                    ? "No transactions yet. Deposit funds to get started."
                    : `No ${filter !== "all" ? filter : ""} transactions found.`}
                </p>
              </div>
            )}

            {!loading && !error && filtered.length > 0 && (
              <>
                <div className="overflow-x-auto">
                  <table className="w-full">
                    <thead>
                      {table.getHeaderGroups().map((hg) => (
                        <tr key={hg.id} className="border-b border-border/50">
                          {hg.headers.map((header) => (
                            <th
                              key={header.id}
                              className="text-left text-xs font-medium text-muted-foreground px-4 py-3 cursor-pointer select-none hover:text-foreground transition-colors"
                              onClick={header.column.getToggleSortingHandler()}
                            >
                              <div className="flex items-center gap-1">
                                {flexRender(header.column.columnDef.header, header.getContext())}
                                {{
                                  asc: " \u25B2",
                                  desc: " \u25BC",
                                }[header.column.getIsSorted() as string] ?? null}
                              </div>
                            </th>
                          ))}
                        </tr>
                      ))}
                    </thead>
                    <tbody>
                      {table.getRowModel().rows.map((row) => (
                        <tr
                          key={row.id}
                          className="cursor-pointer transition-colors hover:bg-surface-hover"
                          onClick={() => window.location.href = `/transactions/${row.original.id}`}
                        >
                          {row.getVisibleCells().map((cell) => (
                            <td key={cell.id} className="px-4 py-3.5 border-b border-border/30 last:border-0">
                              {flexRender(cell.column.columnDef.cell, cell.getContext())}
                            </td>
                          ))}
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
                <div className="flex items-center justify-between px-4 py-3 border-t border-border/50">
                  <div className="flex items-center gap-2">
                    <span className="text-xs text-muted-foreground">Rows per page</span>
                    <select
                      value={pageSize}
                      onChange={(e) => { setPageSize(Number(e.target.value)); setPageIndex(0) }}
                      className="h-8 rounded-md border border-input bg-background px-2 text-xs"
                    >
                      {[10, 25, 50, 100].map((s) => (
                        <option key={s} value={s}>{s}</option>
                      ))}
                    </select>
                  </div>
                  <div className="flex items-center gap-1">
                    <Button
                      variant="outline"
                      size="sm"
                      disabled={pageIndex === 0}
                      onClick={() => setPageIndex((p) => Math.max(0, p - 1))}
                      className="h-8 px-2 text-xs"
                    >
                      Prev
                    </Button>
                    {Array.from({ length: totalPages }, (_, i) => i)
                      .filter((i) => {
                        if (totalPages <= 7) return true
                        if (i === 0 || i === totalPages - 1) return true
                        if (Math.abs(i - pageIndex) <= 1) return true
                        return false
                      })
                      .map((i, idx, arr) => {
                        const showEllipsis = idx > 0 && i - arr[idx - 1] > 1
                        return (
                          <span key={i} className="flex items-center">
                            {showEllipsis && <span className="px-1 text-xs text-muted-foreground">&hellip;</span>}
                            <Button
                              variant={i === pageIndex ? "default" : "outline"}
                              size="sm"
                              onClick={() => setPageIndex(i)}
                              className="h-8 min-w-[28px] px-1 text-xs"
                            >
                              {i + 1}
                            </Button>
                          </span>
                        )
                      })}
                    <Button
                      variant="outline"
                      size="sm"
                      disabled={pageIndex >= totalPages - 1}
                      onClick={() => setPageIndex((p) => Math.min(totalPages - 1, p + 1))}
                      className="h-8 px-2 text-xs"
                    >
                      Next
                    </Button>
                  </div>
                </div>
              </>
            )}
          </CardContent>
        </Card>
      </main>

      <PageFooter
        right={
          <span>{filtered.length} transaction{filtered.length !== 1 ? "s" : ""}</span>
        }
      />
    </>
  )
}

