import { useState } from "react"
import { Link } from "@tanstack/react-router"
import { ArrowLeft, Bell, LogOut, Save, KeyRound } from "lucide-react"
import { signOut, useSession } from "../lib/auth-client"
import { Button } from "../components/ui/button"
import { Input } from "../components/ui/input"
import { Label } from "../components/ui/label"
import { Card, CardContent, CardHeader, CardTitle } from "../components/ui/card"
import { Skeleton } from "../components/ui/skeleton"
import PageHeader from "../components/ui/page-header"
import PageFooter from "../components/ui/page-footer"

export default function AccountSettingsPage() {
  const { data: session, isPending } = useSession()
  const user = session?.user

  const [name, setName] = useState(user?.name ?? "")
  const [saving, setSaving] = useState(false)
  const [saveMessage, setSaveMessage] = useState<string | null>(null)
  const [nameError, setNameError] = useState<string | null>(null)

  const [currentPassword, setCurrentPassword] = useState("")
  const [newPassword, setNewPassword] = useState("")
  const [confirmPassword, setConfirmPassword] = useState("")
  const [changingPassword, setChangingPassword] = useState(false)
  const [passwordMessage, setPasswordMessage] = useState<string | null>(null)
  const [passwordError, setPasswordError] = useState<string | null>(null)

  async function handleSaveName() {
    if (!name.trim()) {
      setNameError("Name cannot be empty")
      return
    }
    setSaving(true)
    setSaveMessage(null)
    setNameError(null)
    try {
      const res = await fetch("/api/auth/update-user", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ name: name.trim() }),
      })
      const json = await res.json()
      if (!json?.user) throw new Error(json?.error ?? json?.statusText ?? "Failed to update name")
      setSaveMessage("Saved")
    } catch (err) {
      setNameError(err instanceof Error ? err.message : "Failed to save")
    } finally {
      setSaving(false)
    }
  }

  async function handleChangePassword(e: React.FormEvent) {
    e.preventDefault()
    if (newPassword !== confirmPassword) {
      setPasswordError("Passwords do not match")
      return
    }
    if (newPassword.length < 8) {
      setPasswordError("Password must be at least 8 characters")
      return
    }
    setChangingPassword(true)
    setPasswordMessage(null)
    setPasswordError(null)
    try {
      const res = await fetch("/api/auth/change-password", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ currentPassword, newPassword }),
      })
      const json = await res.json()
      if (!json?.status) throw new Error(json?.error ?? json?.statusText ?? "Failed to change password")
      setPasswordMessage("Password changed")
      setCurrentPassword("")
      setNewPassword("")
      setConfirmPassword("")
    } catch (err) {
      setPasswordError(err instanceof Error ? err.message : "Failed to change password")
    } finally {
      setChangingPassword(false)
    }
  }

  const handleSignOut = async () => {
    await signOut()
  }

  if (isPending || !user) {
    return (
      <div className="flex-1 mx-auto w-full max-w-lg px-8 py-8 space-y-6">
        <Skeleton className="h-8 w-48" />
        <Card>
          <CardContent className="p-6 space-y-4">
            <Skeleton className="size-16 rounded-full mx-auto" />
            <Skeleton className="h-5 w-32 mx-auto" />
            <Skeleton className="h-4 w-48 mx-auto" />
          </CardContent>
        </Card>
      </div>
    )
  }

  const memberSince = user.createdAt
    ? new Date(user.createdAt).toLocaleDateString("en-US", { month: "long", year: "numeric" })
    : null

  return (
    <>
      <PageHeader
        title="Account Settings"
        email={user.email}
        beforeTitle={
          <Link
            to="/account"
            className="inline-flex items-center justify-center w-8 h-8 rounded-md text-muted-foreground hover:text-foreground hover:bg-muted transition-colors"
            aria-label="Back to Account"
          >
            <ArrowLeft className="size-4" />
          </Link>
        }
      />

      <main className="flex-1 mx-auto w-full max-w-lg px-8 py-8 space-y-8">
        <Card>
          <CardHeader>
            <CardTitle className="text-sm font-medium">Profile</CardTitle>
          </CardHeader>
          <CardContent className="space-y-5">
            <div className="flex flex-col items-center gap-3">
              <div className="size-16 rounded-full bg-primary/10 flex items-center justify-center text-xl font-semibold text-primary">
                {user.name?.charAt(0).toUpperCase() ?? "?"}
              </div>
              <div className="text-center">
                <p className="text-sm font-medium text-foreground">{user.name}</p>
                <p className="text-xs text-muted-foreground">{user.email}</p>
                {memberSince && (
                  <p className="text-xs text-muted-foreground mt-0.5">Member since {memberSince}</p>
                )}
              </div>
            </div>

            <div className="space-y-1.5">
              <Label htmlFor="settings-name">Display name</Label>
              <Input
                id="settings-name"
                value={name}
                onChange={(e) => setName(e.target.value)}
              />
              {nameError && <p className="text-xs text-destructive">{nameError}</p>}
              {saveMessage && <p className="text-xs text-success">{saveMessage}</p>}
            </div>

            <Button
              size="sm"
              onClick={handleSaveName}
              disabled={saving || name === user.name}
              className="w-full"
            >
              <Save className="size-4 mr-1" />
              {saving ? "Saving..." : "Save"}
            </Button>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle className="text-sm font-medium">Security</CardTitle>
          </CardHeader>
          <CardContent>
            <form onSubmit={handleChangePassword} className="space-y-4">
              <div className="space-y-1.5">
                <Label htmlFor="settings-current-password">Current password</Label>
                <Input
                  id="settings-current-password"
                  type="password"
                  value={currentPassword}
                  onChange={(e) => setCurrentPassword(e.target.value)}
                  required
                />
              </div>
              <div className="space-y-1.5">
                <Label htmlFor="settings-new-password">New password</Label>
                <Input
                  id="settings-new-password"
                  type="password"
                  value={newPassword}
                  onChange={(e) => setNewPassword(e.target.value)}
                  required
                  minLength={8}
                />
              </div>
              <div className="space-y-1.5">
                <Label htmlFor="settings-confirm-password">Confirm new password</Label>
                <Input
                  id="settings-confirm-password"
                  type="password"
                  value={confirmPassword}
                  onChange={(e) => setConfirmPassword(e.target.value)}
                  required
                  minLength={8}
                />
              </div>
              {passwordError && <p className="text-xs text-destructive">{passwordError}</p>}
              {passwordMessage && <p className="text-xs text-success">{passwordMessage}</p>}
              <Button
                type="submit"
                size="sm"
                disabled={changingPassword || !currentPassword || !newPassword || !confirmPassword}
                className="w-full"
              >
                <KeyRound className="size-4 mr-1" />
                {changingPassword ? "Changing..." : "Change password"}
              </Button>
            </form>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle className="text-sm font-medium">Preferences</CardTitle>
          </CardHeader>
          <CardContent>
            <Link
              to="/notifications/preferences"
              className="flex items-center gap-3 rounded-lg px-3 py-2.5 text-sm text-foreground hover:bg-surface-hover transition-colors -mx-3"
            >
              <Bell className="size-4 text-muted-foreground" />
              <span className="flex-1">Notification preferences</span>
              <span className="text-xs text-muted-foreground">Configure</span>
            </Link>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle className="text-sm font-medium text-destructive">Sign out</CardTitle>
          </CardHeader>
          <CardContent>
            <p className="text-xs text-muted-foreground mb-3">
              You will be redirected to the sign-in page.
            </p>
            <Button variant="destructive" size="sm" onClick={handleSignOut} className="w-full">
              <LogOut className="size-4 mr-1" />
              Sign out
            </Button>
          </CardContent>
        </Card>
      </main>

      <PageFooter />
    </>
  )
}

import { useEffect, useState, useCallback, useMemo, useRef } from "react"
import { Search, X } from "lucide-react"
import { signOut, useSession } from "../lib/auth-client"
import { Button } from "../components/ui/button"
import { Input } from "../components/ui/input"
import { Badge } from "../components/ui/badge"
import { Skeleton } from "../components/ui/skeleton"
import PageHeader from "../components/ui/page-header"
import PageFooter from "../components/ui/page-footer"
import { formatCurrency } from "@/lib/utils"
import type { IWalletTransaction, WaveResponse, ITransaction, TBankAccountNumber } from "@/types"

type ResourceType = "transaction" | "account" | "notification"

interface SearchResult {
  id: string
  type: ResourceType
  title: string
  subtitle: string
  href: string
  amount?: string
  timestamp: string
  status?: string
}

interface RawNotification {
  id: string
  title: string
  message: string
  type: "info" | "warning" | "error"
  timestamp: string
  read: boolean
}

const TABS: { key: ResourceType | "all"; label: string }[] = [
  { key: "all", label: "All" },
  { key: "transaction", label: "Transactions" },
  { key: "account", label: "Accounts" },
  { key: "notification", label: "Notifications" },
]

function formatDate(iso: string): string {
  const d = new Date(iso)
  const now = new Date()
  const diffMs = now.getTime() - d.getTime()
  const diffMins = Math.floor(diffMs / 60000)
  if (diffMins < 1) return "Just now"
  if (diffMins < 60) return `${diffMins}m ago`
  const diffHours = Math.floor(diffMins / 60)
  if (diffHours < 24) return `${diffHours}h ago`
  const diffDays = Math.floor(diffHours / 24)
  if (diffDays < 7) return `${diffDays}d ago`
  return d.toLocaleDateString("en-US", { month: "short", day: "numeric" })
}

function typeBadgeVariant(type: ResourceType): "default" | "secondary" | "outline" {
  switch (type) {
    case "transaction": return "default"
    case "account": return "secondary"
    case "notification": return "outline"
  }
}

function typeLabel(type: ResourceType): string {
  switch (type) {
    case "transaction": return "Transaction"
    case "account": return "Account"
    case "notification": return "Notification"
  }
}

export default function SearchPage() {
  const { data: session } = useSession()
  const user = session!.user

  const [query, setQuery] = useState("")
  const [activeTab, setActiveTab] = useState<ResourceType | "all">("all")
  const inputRef = useRef<HTMLInputElement>(null)

  const [transactions, setTransactions] = useState<ITransaction[]>([])
  const [accounts, setAccounts] = useState<IWalletTransaction[]>([])
  const [notifications, setNotifications] = useState<RawNotification[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  const fetchAll = useCallback(async () => {
    setLoading(true)
    setError(null)
    try {
      const [txRes, acctRes, notifRes] = await Promise.all([
        fetch(`/api/wallet/users/${user.id}/transactions`),
        fetch(`/api/wallet/users/${user.id}/accounts`),
        fetch(`/api/notification/users/${user.id}/notifications?limit=100`),
      ])

      const [txJson, acctJson, notifJson]: [
        WaveResponse<ITransaction[]>,
        WaveResponse<IWalletTransaction[]>,
        { ok: boolean; data?: RawNotification[] }
      ] = await Promise.all([
        txRes.json(),
        acctRes.json(),
        notifRes.json(),
      ])

      if (txJson.ok) setTransactions(txJson.data)
      if (acctJson.ok) setAccounts(acctJson.data)
      if (notifJson.ok) setNotifications(notifJson.data ?? [])
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to load data")
    } finally {
      setLoading(false)
    }
  }, [user.id])

  useEffect(() => {
    fetchAll()
  }, [fetchAll])

  useEffect(() => {
    inputRef.current?.focus()
  }, [])

  const results = useMemo(() => {
    const q = query.trim().toLowerCase()
    const items: SearchResult[] = []

    if (!q) return items

    for (const tx of transactions) {
      const senderStr = String(tx.senderAccountNumber)
      const receiverStr = String(tx.receiverAccountNumber)
      const searchable = [
        tx.senderName.toLowerCase(),
        tx.receiverName.toLowerCase(),
        senderStr,
        receiverStr,
        tx.amount,
        tx.status,
      ]
      if (!searchable.some((s) => s.includes(q))) continue

      items.push({
        id: `tx-${tx.id}`,
        type: "transaction",
        title: tx.senderName === tx.receiverName
          ? "Deposit"
          : `To ${tx.receiverName}`,
        subtitle: tx.senderName === tx.receiverName
          ? `From ${tx.senderName}`
          : `From ${tx.senderName}`,
        amount: tx.amount,
        status: tx.status,
        timestamp: tx.createdAt,
        href: `/transactions/${tx.id}`,
      })
    }

    for (const acct of accounts) {
      const searchable = [
        acct.name.toLowerCase(),
        String(acct.accountNumber),
        String(acct.balance),
      ]
      if (!searchable.some((s) => s.includes(q))) continue

      items.push({
        id: `acct-${acct.id}`,
        type: "account",
        title: acct.name,
        subtitle: `Account ${acct.accountNumber}`,
        amount: String(acct.balance),
        timestamp: acct.createdAt instanceof Date
          ? acct.createdAt.toISOString()
          : String(acct.createdAt),
        href: `/account/${acct.accountNumber}`,
      })
    }

    for (const notif of notifications) {
      const searchable = [
        notif.title.toLowerCase(),
        notif.message.toLowerCase(),
      ]
      if (!searchable.some((s) => s.includes(q))) continue

      items.push({
        id: `notif-${notif.id}`,
        type: "notification",
        title: notif.title,
        subtitle: notif.message,
        timestamp: notif.timestamp,
        href: "/notifications",
      })
    }

    items.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime())
    return items
  }, [query, transactions, accounts, notifications])

  const filteredResults = useMemo(() => {
    if (activeTab === "all") return results
    return results.filter((r) => r.type === activeTab)
  }, [results, activeTab])

  const handleSignOut = async () => {
    await signOut()
  }

  return (
    <>
      <PageHeader
        title="Search"
        email={user.email}
        actions={
          <Button variant="ghost" size="sm" onClick={handleSignOut}>
            Sign Out
          </Button>
        }
      />

      <main className="flex-1 mx-auto w-full max-w-3xl px-8 py-8 space-y-6">
        <div className="relative">
          <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 size-5 text-muted-foreground pointer-events-none" />
          <Input
            ref={inputRef}
            placeholder="Search transactions, accounts, notifications..."
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            className="pl-10 pr-10 h-12 text-base rounded-xl"
          />
          {query && (
            <button
              onClick={() => setQuery("")}
              className="absolute right-3.5 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground transition-colors"
              aria-label="Clear search"
            >
              <X className="size-5" />
            </button>
          )}
        </div>

        {loading && (
          <div className="space-y-3">
            {Array.from({ length: 6 }).map((_, i) => (
              <div key={i} className="flex items-center gap-3 px-3 py-3">
                <Skeleton className="size-8 rounded-full shrink-0" />
                <div className="flex-1 space-y-1.5">
                  <Skeleton className="h-4 w-48" />
                  <Skeleton className="h-3 w-32" />
                </div>
                <Skeleton className="h-4 w-16" />
              </div>
            ))}
          </div>
        )}

        {error && !loading && (
          <div className="flex flex-col items-center gap-3 py-16 text-center">
            <p className="text-sm text-muted-foreground">{error}</p>
            <Button variant="outline" size="sm" onClick={fetchAll}>
              Retry
            </Button>
          </div>
        )}

        {!loading && !error && query && (
          <>
            <div className="flex flex-wrap items-center gap-2">
              {TABS.map((tab) => {
                const count = tab.key === "all"
                  ? results.length
                  : results.filter((r) => r.type === tab.key).length
                return (
                  <button
                    key={tab.key}
                    onClick={() => setActiveTab(tab.key)}
                    className={`inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-medium transition-colors ${
                      activeTab === tab.key
                        ? "bg-primary text-primary-foreground"
                        : "bg-surface text-muted-foreground hover:text-foreground"
                    }`}
                  >
                    {tab.label}
                    <span className="text-[10px] opacity-70">({count})</span>
                  </button>
                )
              })}
            </div>

            {filteredResults.length === 0 ? (
              <div className="flex flex-col items-center gap-2 py-16 text-center">
                <p className="text-sm text-muted-foreground">No results found for &ldquo;{query}&rdquo;</p>
              </div>
            ) : (
              <div>
                <p className="text-xs text-muted-foreground mb-3">
                  {filteredResults.length} result{filteredResults.length !== 1 ? "s" : ""}
                </p>
                <div className="divide-y divide-border/30">
                  {filteredResults.map((result) => (
                    <a
                      key={result.id}
                      href={result.href}
                      className="flex items-center gap-3 px-3 py-3 rounded-lg transition-colors hover:bg-surface-hover -mx-3"
                    >
                      <Badge variant={typeBadgeVariant(result.type)} className="shrink-0 text-[10px] px-1.5 py-0">
                        {typeLabel(result.type)}
                      </Badge>
                      <div className="flex-1 min-w-0">
                        <p className="text-sm font-medium text-foreground truncate">{result.title}</p>
                        <p className="text-xs text-muted-foreground truncate">{result.subtitle}</p>
                      </div>
                      <div className="text-right shrink-0">
                        {result.amount && (
                          <p className="font-mono text-sm font-semibold whitespace-nowrap tabular-nums">
                            {formatCurrency(result.amount)}
                          </p>
                        )}
                        <p className="text-[10px] text-muted-foreground">{formatDate(result.timestamp)}</p>
                      </div>
                    </a>
                  ))}
                </div>
              </div>
            )}
          </>
        )}

        {!loading && !error && !query && (
          <div className="flex flex-col items-center gap-2 py-16 text-center">
            <Search className="size-10 text-muted-foreground/40 mb-2" />
            <p className="text-sm text-muted-foreground">
              Search across your transactions, accounts, and notifications
            </p>
          </div>
        )}
      </main>

      <PageFooter />
    </>
  )
}

import { useEffect, useState, useCallback } from "react"
import { useSession } from "../lib/auth-client"
import { Card, CardContent, CardHeader, CardTitle } from "../components/ui/card"
import { Button } from "../components/ui/button"
import { Skeleton } from "../components/ui/skeleton"
import PageHeader from "../components/ui/page-header"
import PageFooter from "../components/ui/page-footer"

interface NotificationPreference {
  userId: string
  eventType: "deposit" | "transfer_incoming" | "transfer_outgoing"
  enabled: boolean
}

const EVENT_LABELS: Record<string, string> = {
  deposit: "Deposits",
  transfer_incoming: "Money Received",
  transfer_outgoing: "Money Sent",
}

const EVENT_DESCRIPTIONS: Record<string, string> = {
  deposit: "When money is added to your account",
  transfer_incoming: "When someone sends you money",
  transfer_outgoing: "When you send money to someone",
}

export default function NotificationPreferencesPage() {
  const { data: session } = useSession()
  const user = session!.user
  const [preferences, setPreferences] = useState<NotificationPreference[]>([])
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState<string | null>(null)
  const [error, setError] = useState<string | null>(null)

  const fetchPreferences = useCallback(async () => {
    try {
      setLoading(true)
      setError(null)
      const res = await fetch(`/api/notification/users/${user.id}/notification-preferences`)
      if (!res.ok) throw new Error(`HTTP ${res.status}`)
      const json = await res.json()
      setPreferences(json.data ?? [])
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to load preferences")
    } finally {
      setLoading(false)
    }
  }, [user.id])

  useEffect(() => {
    fetchPreferences()
  }, [fetchPreferences])

  const togglePreference = async (eventType: string, currentEnabled: boolean) => {
    setSaving(eventType)
    try {
      const res = await fetch(`/api/notification/users/${user.id}/notification-preferences`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ eventType, enabled: !currentEnabled }),
      })
      if (!res.ok) throw new Error(`HTTP ${res.status}`)
      const json = await res.json()
      setPreferences((prev) => {
        const existing = prev.find((p) => p.eventType === eventType)
        if (existing) {
          return prev.map((p) => (p.eventType === eventType ? json.data : p))
        }
        return [...prev, json.data]
      })
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to update preference")
    } finally {
      setSaving(null)
    }
  }

  const allEventTypes = ["deposit", "transfer_incoming", "transfer_outgoing"]
  const preferenceMap = new Map(preferences.map((p) => [p.eventType, p]))

  return (
    <>
      <PageHeader
        title="Notification Preferences"
        email={user.email}
      />

      <main className="flex-1 mx-auto w-full max-w-2xl px-8 py-6">
        {loading && (
          <div className="flex flex-col gap-3">
            {Array.from({ length: 3 }).map((_, i) => (
              <Skeleton key={i} className="h-20 w-full rounded-lg" />
            ))}
          </div>
        )}

        {error && !loading && (
          <div className="flex flex-col items-center justify-center gap-4 py-16 text-center">
            <p className="text-muted-foreground">{error}</p>
            <Button variant="outline" onClick={fetchPreferences}>Retry</Button>
          </div>
        )}

        {!loading && !error && (
          <div className="flex flex-col gap-2">
            {allEventTypes.map((eventType) => {
              const pref = preferenceMap.get(eventType)
              const enabled = pref?.enabled ?? true
              return (
                <Card key={eventType}>
                  <CardContent className="flex items-center justify-between py-4 px-5">
                    <div className="space-y-0.5">
                      <p className="text-sm font-medium text-foreground">{EVENT_LABELS[eventType]}</p>
                      <p className="text-xs text-muted-foreground">{EVENT_DESCRIPTIONS[eventType]}</p>
                    </div>
                    <button
                      type="button"
                      role="switch"
                      aria-checked={enabled}
                      disabled={saving === eventType}
                      onClick={() => togglePreference(eventType, enabled)}
                      className={`relative h-6 w-11 rounded-full transition-colors ${
                        saving === eventType ? "opacity-50 pointer-events-none" : ""
                      } ${
                        enabled ? "bg-primary" : "bg-input"
                      }`}
                    >
                      <span
                        className={`block h-5 w-5 rounded-full bg-background shadow-sm transition-transform ${
                          enabled ? "translate-x-[22px]" : "translate-x-[2px]"
                        }`}
                      />
                    </button>
                  </CardContent>
                </Card>
              )
            })}
          </div>
        )}
      </main>

      <PageFooter
        left="Wave Notification Center"
        right={<span>Preferences</span>}
      />
    </>
  )
}

